<script>
(function () {
  'use strict';

  var form = document.getElementById('signup');
  var success = document.getElementById('success');
  var toggle = document.getElementById('toggle-password');

  // La validación la gestiona este script; se desactivan los globos nativos del navegador.
  form.noValidate = true;

  var EMAIL_RE = /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/;
  var HOST_RE = /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59})$/i;
  var NAME_RE = /^[\p{L}\p{M}][\p{L}\p{M}\s.'’-]*$/u;
  var WEBSITE_MSG = 'Introduce una dirección web válida, por ejemplo https://ejemplo.com.';

  // Une una lista en español: "a, b y c".
  function joinList(items) {
    if (items.length < 2) return items.join('');
    return items.slice(0, -1).join(', ') + ' y ' + items[items.length - 1];
  }

  // Cada campo define: cómo normalizar el valor, el mensaje si está vacío
  // y una función check que devuelve un mensaje de error o '' si es válido.
  var fields = [
    {
      id: 'name',
      normalize: function (v) { return v.trim().replace(/\s+/g, ' '); },
      emptyMessage: 'Escribe tu nombre completo.',
      check: function (v) {
        if (v.length < 2) return 'El nombre debe tener al menos 2 caracteres.';
        if (v.length > 100) return 'El nombre no puede superar los 100 caracteres.';
        if (!NAME_RE.test(v)) return 'El nombre solo puede contener letras, espacios, guiones y apóstrofos.';
        return '';
      }
    },
    {
      id: 'email',
      normalize: function (v) { return v.trim(); },
      emptyMessage: 'Escribe tu correo electrónico.',
      check: function (v) {
        if (v.length > 254 || !EMAIL_RE.test(v)) {
          return 'Introduce un correo válido, por ejemplo nombre@ejemplo.com.';
        }
        return '';
      }
    },
    {
      id: 'website',
      // Si falta el protocolo ("ejemplo.com"), se asume https://.
      normalize: function (v) {
        v = v.trim();
        if (v && !/^[a-z][a-z0-9+.-]*:\/\//i.test(v)) v = 'https://' + v;
        return v;
      },
      emptyMessage: 'Escribe la dirección de tu sitio web.',
      check: function (v) {
        if (/\s/.test(v)) return WEBSITE_MSG;
        var url;
        try {
          url = new URL(v);
        } catch (e) {
          return WEBSITE_MSG;
        }
        if (url.protocol !== 'http:' && url.protocol !== 'https:') {
          return 'La dirección debe empezar por http:// o https://.';
        }
        if (url.username || url.password || !HOST_RE.test(url.hostname)) return WEBSITE_MSG;
        return '';
      }
    },
    {
      id: 'password',
      normalize: function (v) { return v; }, // La contraseña no se modifica nunca.
      emptyMessage: 'Elige una contraseña.',
      check: function (v) {
        var missing = [];
        if (v.length < 8) missing.push('8 caracteres');
        if (!/\p{Ll}/u.test(v)) missing.push('una minúscula');
        if (!/\p{Lu}/u.test(v)) missing.push('una mayúscula');
        if (!/\d/.test(v)) missing.push('un número');
        return missing.length ? 'La contraseña debe incluir al menos ' + joinList(missing) + '.' : '';
      }
    }
  ];

  fields.forEach(function (field) {
    field.input = document.getElementById(field.id);
    field.error = document.getElementById(field.id + '-error');
  });

  function showError(field, message) {
    field.error.textContent = message;
    field.error.hidden = !message;
    if (message) {
      field.input.setAttribute('aria-invalid', 'true');
    } else {
      field.input.removeAttribute('aria-invalid');
    }
  }

  // Valida un campo y muestra u oculta su mensaje de error.
  // Con commit = true, escribe el valor normalizado de vuelta en el campo.
  function validate(field, commit) {
    var input = field.input;
    var value = field.normalize(input.value);
    if (commit && value !== input.value) input.value = value;

    var message = '';
    if (value === '') {
      if (input.required) message = field.emptyMessage;
    } else {
      message = field.check(value);
    }

    showError(field, message);
    return !message;
  }

  fields.forEach(function (field) {
    // Al salir de un campo con contenido, se valida.
    field.input.addEventListener('blur', function () {
      if (field.input.value !== '') validate(field, true);
    });

    // Mientras se corrige un campo con error, el mensaje se actualiza al momento.
    field.input.addEventListener('input', function () {
      success.hidden = true;
      if (field.input.hasAttribute('aria-invalid')) validate(field, false);
    });
  });

  function setPasswordVisible(visible) {
    var password = document.getElementById('password');
    password.type = visible ? 'text' : 'password';
    toggle.textContent = visible ? 'Ocultar' : 'Mostrar';
    toggle.setAttribute('aria-label', visible ? 'Ocultar contraseña' : 'Mostrar contraseña');
  }

  toggle.addEventListener('click', function () {
    setPasswordVisible(document.getElementById('password').type === 'password');
  });

  form.addEventListener('submit', function (event) {
    success.hidden = true;

    var invalid = fields.filter(function (field) {
      return !validate(field, true);
    });

    if (invalid.length > 0) {
      event.preventDefault();
      invalid[0].input.focus();
      return;
    }

    // Datos válidos: con atributo action, el navegador envía el formulario.
    // Sin action (demostración), se muestra una confirmación en la propia página.
    if (!form.hasAttribute('action')) {
      event.preventDefault();
      form.reset();
      setPasswordVisible(false);
      success.hidden = false;
      success.focus();
    }
  });
})();
</script>
